def test_function_words_and_short_words_do_not_find_unrelated_passages(self):
    library = self.library()
    for document in fx.CORPUS:
        self.add(library, document, "md")
    for query in ("статьи про тревожность", "dropout per condition in the trial", "депрессия без лечения"):
        self.assertEqual(library.search(query).total, 0, query)   # today 6, 5, 2
    self.assertNotIn(rl.QueryTerm("chi", True), rl.query_terms("chi-square test"))  # today present

def test_pdf_ligatures_are_searchable(self):
    self.assertEqual(rl.tokens(rl.clean_text("signiﬁcant eﬀect coeﬃcient")),
                     ["significant", "effect", "coefficient"])   # today ['signiﬁcant', 'eﬀect', 'coeﬃcient']

def test_latvian_endings_do_not_cut_english_words(self):
    library = self.library()
    for document in fx.CORPUS:
        self.add(library, document, "md")
    self.assertEqual(library.search("socioeconomic status of parents").total, 0)  # today 3 (stat… → 'statements')

def test_stopwords_are_folded_like_the_query(self):
    self.assertEqual([t.text for t in rl.query_terms("её ответы")], ["ответ"])        # today ['ее', 'ответ']
    self.assertEqual(rl.query_terms("ka ari pec tam"), rl.query_terms("kā arī pēc tam"))  # today differ

def test_common_inflections_are_stemmed(self):
    self.assertEqual(rl.stem("социальных"), "социальн")      # today 'социальных'
    self.assertEqual(rl.stem("grupam"), rl.stem("grupām"))   # today 'grupam' vs 'grup'

def test_numbers_inside_a_page_are_kept(self):
    text = rl._assemble(rl._pdf_blocks([("Condition N", 10.0), ("Control", 10.0), ("120", 10.0)]), 1).text
    self.assertIn("120", text)   # today 'Condition N Control'

def test_soft_hyphen_at_line_end_is_joined(self):
    self.assertEqual(rl._dehyphenate(["The investi­", "gation was preregistered."])[0],
                     "The investigation")   # today 'The investi\xad'

